    "author": "",
    "description": "36氪获悉，复星医药9月6日H股公告，公司拟自2026年8月27日起12个月内回购H股，拟回购H股资金总额不超过港币10亿元。公司将根据H股回购授权及市场情况等因素确定该等已回购H股之用途，包括但不限于注销已回购之H股或将其作为库存股份持有。",
    "content": "36氪获悉，复星医药9月6日H股公告，公司拟自2026年8月27日起12个月内回购H股，拟回购H股资金总额不超过港币10亿元。公司将根据H股回购授权及市场情况等因素确定该等已回购H股之用途，包括但不限于注销已回购之H股或将其作为库存股份持有。"
