    "content": "记者从水利部了解到，水文应急监测显示，西藏吉隆原普热普强藏布堰塞湖下游小规模滑坡体无明显变化，河道过流正常，河道两侧山体受泥石流影响明显，仍存在滑坡体进一步垮塌形成新堰塞湖的风险。尼泊尔错坚河冲击坑上下游过流正常。前期排查的14个冰湖整体稳定。"
