    "description": "新华社北京9月6日电（记者张千千）9月6日，中国人保公告向特定对象发行A股股票预案。本次发行拟由财政部以现金方式认购，募集资金规模不超过150亿元人民币，在扣除相关发行费用后全部用于补充公司的资本金。本次资本补充有助于中国人保进一步夯实资本基础，提升稳健经营能力和风险抵御能力，更好发挥保险业的经济减震器和社会稳定器功能。",
    "content": "新华社北京9月6日电（记者张千千）9月6日，中国人保公告向特定对象发行A股股票预案。本次发行拟由财政部以现金方式认购，募集资金规模不超过150亿元人民币，在扣除相关发行费用后全部用于补充公司的资本金。本次资本补充有助于中国人保进一步夯实资本基础，提升稳健经营能力和风险抵御能力，更好发挥保险业的经济减震器和社会稳定器功能。"
