    "content": "据中国驻挪威大使馆微信公众号消息，2026年9月5日，中华人民共和国新任驻挪威王国特命全权大使周景兴抵挪履新。 周大使在机场发表书面讲话表示，挪威是最早承认新中国的西方国家之一。建交72年来，两国关系经受国际风云考验，保持稳定、可持续发展。中方愿同挪方落实好两国领导人重要共识，坚持伙伴关系定位，密切高层交往，深化互利共赢合作，加强多边协作，持续为两国人民带来福祉，共同为世界和平与发展作出贡献。 周大使表示，期待同挪各界人士携手努力，增进了解、深化友谊，推动两国政治互信、务实合作、人文交流迈上新台阶，谱写中挪关系美好…"
