    "title": "多位储能业内人士：有关部门正全面摸底产能 企业新建产能项目审批暂缓",
    "link": "https://36kr.com/newsflashes/3971580193911040?f=rss",
    "pub_date": "2026-09-06 15:00:17",
    "author": "",
    "description": "记者日前从多位产业链人士获悉，针对当前储能行业产能过剩风险加剧，有关部门近期正全面摸排现有及规划中的产能底数，储能电芯是重点领域之一，对尚处规划阶段、未正式开工的项目暂缓审批和推进，已备案且在建的项目不受影响。据多位业内人士了解，此次收紧并非全面叫停，后续有望根据市场实际需求动态调整。（财联社）",
    "content": "记者日前从多位产业链人士获悉，针对当前储能行业产能过剩风险加剧，有关部门近期正全面摸排现有及规划中的产能底数，储能电芯是重点领域之一，对尚处规划阶段、未正式开工的项目暂缓审批和推进，已备案且在建的项目不受影响。据多位业内人士了解，此次收紧并非全面叫停，后续有望根据市场实际需求动态调整。（财联社）"
