    "category": "新闻",
    "title": "瑞金至延安，长征出发地到落脚点高铁直达",
    "link": "http://www.news.cn/20260906/b375bf35e5264349a4463c39c673d16d/c.html",
    "pub_date": "2026-09-06 14:45:14",
    "author": "余刚",
    "description": "9月6日上午，G3998次复兴号列车驶出瑞金站，奔向千里之外的延安，标志着中央红军长征出发地江西瑞金与落脚点陕西延安实现高铁直达。 记者：解文韬、余刚、陈昌奇 编导：薛宁婧 新华社音视频部制作",
    "content": "9月6日上午，G3998次复兴号列车驶出瑞金站，奔向千里之外的延安，标志着中央红军长征出发地江西瑞金与落脚点陕西延安实现高铁直达。 记者：解文韬、余刚、陈昌奇 编导：薛宁婧 新华社音视频部制作"
