    "author": "刘润芝",
    "description": "提到黑色素瘤，不少人会心生畏惧，这种被称为“癌中之王”的皮肤恶性肿瘤，最大特点是“转移快”和“隐匿强”。天津市中医药研究院附属医院皮肤外科主任医师邢卫斌提示，黑色素瘤虽凶险，但并非不可预防，关键在于识别危险信号，做好早期筛查。 记者：刘润芝 素材支持：天津市中医药研究院附属医院 新华社音视频部制作",
