    "author": "澎湃新闻记者 蒋乐来",
    "description": "9月5日晚，陈金敖剪下了阳台上的葫芦。过去一段时间，浙江绍兴“书圣故里”景区里这个长着7个葫芦的阳台和这位阳台上的爷爷，成了无数游客收获治愈的风景。然而连日来越来越大的人流量、越来越多的互动让老人愈发疲惫。 2026年9月3日，浙江绍兴，书圣故里探花桥旁，75岁老人因阳台种植的7个葫芦走红网络，吸引众多游客前来打卡。图为老人在阳台向游客挥手致意。视觉中国 图 陈金敖和妻子沈华玲是一对失独老人，此前他们也曾说网友打开了他们的心。但这个本来…",
    "content": "9月5日晚，陈金敖剪下了阳台上的葫芦。过去一段时间，浙江绍兴“书圣故里”景区里这个长着7个葫芦的阳台和这位阳台上的爷爷，成了无数游客收获治愈的风景。然而连日来越来越大的人流量、越来越多的互动让老人愈发疲惫。 2026年9月3日，浙江绍兴，书圣故里探花桥旁，75岁老人因阳台种植的7个葫芦走红网络，吸引众多游客前来打卡。图为老人在阳台向游客挥手致意。视觉中国 图 陈金敖和妻子沈华玲是一对失独老人，此前他们也曾说网友打开了他们的心。但这个本来看似“你站在桥上看风景，看风景的人在楼上看你”的互相治愈故事，最终在持续的喧闹和…"
