    "content": "新华社雅加达9月6日电（记者李嘉聪）印度尼西亚喀拉喀托之子火山自4日起持续喷发。受此影响，首都雅加达苏加诺-哈达国际机场6日宣布暂停航班起降。目前暂无人员伤亡报告。 据印尼地质部门消息，喀拉喀托之子火山自4日起喷发，5日出现活动增强迹象，并于6日3时53分发生一次较强喷发。印尼火山和地质减灾中心6日说，喀拉喀托之子火山喷发产生的火山灰已扩散至雅加达部分地区以及苏门答腊岛南部。 苏加诺－哈达国际机场6日宣布，受火山喷发活动加剧的影响，暂停航班运行至当地时间13时30分（北京时间14时30分）。印尼交通部民航总局确认，…"
