    "description": "中新网北京9月6日电 (张文晖)蔚蓝深海之上，海上油气平台平稳运转，动力机组持续输出稳定电能。这看似寻常的作业场景，曾长期受制于国外技术垄断。过去数十年，我国海上油气核心动力燃机设备高度依赖进口，不仅采购成本高昂、交付周期漫长，后期备件更换、设备维保均被海外企业牢牢把控，成为制约我国海洋能源开发的关键短板。",
