    "content": "新华社南昌9月6日电 记者在江西省吉安市遂川县高坪镇发生泥石流灾害现场了解到，6日中午，现场救援人员又找到一名失联人员，已无生命体征。截至目前，高坪镇明坑村的泥石流和山体滑坡灾害已造成3人遇难，另有9人失联。"
