    "description": "金秋九月，新学期如约而至。2026年秋季新学期，多项教育新政策从部署走向落地：普通高中招生首次被纳入中小学阳光招生专项行动，科学教育“做中学”在全国初中、小学展开，义务教育阶段所有年级完成三科统编教材替换……一项项政策聚焦质量、守护成长，为新学期带来新气象。 新学期，校园有哪些变化，这些变化释放了哪些信号？ 新的教材、新的课堂、新的实践，校园里的改变还在继续。新学期值得新的期待。 编导：薛宁婧 配音：王帅龙 新华社音视频部制作",
