    "content": "新华社首尔9月6日电（记者姬新龙）韩国关税厅最新统计显示，截至5日下午1时，韩国今年累计出口额为7094亿美元，超过去年全年的7093亿美元历史最高纪录。 韩国总统李在明5日通过社交媒体转述关税厅负责人的报告称，“如果目前稳健的出口势头得以延续，预计将在12月初左右实现全年出口1万亿美元”。 据统计，韩国出口额继2022年达到6836亿美元后，2023年一度回落至6322亿美元，2024年又反弹至6836亿美元，去年达到7093亿美元。 据韩联社报道，今年尽管面临中东局势等严峻外部环境，但在半导体带动下，韩国主要出…"
