    "description": "36氪获悉，据石家庄发布，河北省首个欧盟Next Generation（NG）认证日前花落河北深泽经济开发区，标志着深泽经济开发区在对外开放与绿色低碳发展方面实现里程碑式突破。NG认证有效应对欧盟碳边境调节机制（CBAM）带来的贸易壁垒，深泽经济开发区内全部符合条件的市场主体均可对接欧盟无线电设备指令、企业可持续发展报告指令等国际规则，增强入驻企业在国际市场的话语权与核心竞争力，助力深泽深度参与全球绿色低碳产业链分工。",
    "content": "36氪获悉，据石家庄发布，河北省首个欧盟Next Generation（NG）认证日前花落河北深泽经济开发区，标志着深泽经济开发区在对外开放与绿色低碳发展方面实现里程碑式突破。NG认证有效应对欧盟碳边境调节机制（CBAM）带来的贸易壁垒，深泽经济开发区内全部符合条件的市场主体均可对接欧盟无线电设备指令、企业可持续发展报告指令等国际规则，增强入驻企业在国际市场的话语权与核心竞争力，助力深泽深度参与全球绿色低碳产业链分工。"
