    "description": "新华社伦敦9月6日电（记者张家伟）英国曼彻斯特大学近日发布的一项研究显示，通过可穿戴设备对人体激素水平进行24小时连续监测，可发现常规检测可能遗漏的异常激素波动，这或许有助更早诊断一种常见但容易被忽视的高血压病因——原发性醛固酮增多症。 曼彻斯特大学介绍说，原发性醛固酮增多症是一种激素紊乱疾病，是继发性高血压最常见的病因，还会增加心脏病、中风、糖尿病等疾病风险。由于人体激素水平会随时间变化，加上目前诊断过程较为复杂，一些患者可能迟迟无法…",
    "content": "新华社伦敦9月6日电（记者张家伟）英国曼彻斯特大学近日发布的一项研究显示，通过可穿戴设备对人体激素水平进行24小时连续监测，可发现常规检测可能遗漏的异常激素波动，这或许有助更早诊断一种常见但容易被忽视的高血压病因——原发性醛固酮增多症。 曼彻斯特大学介绍说，原发性醛固酮增多症是一种激素紊乱疾病，是继发性高血压最常见的病因，还会增加心脏病、中风、糖尿病等疾病风险。由于人体激素水平会随时间变化，加上目前诊断过程较为复杂，一些患者可能迟迟无法确诊。 高血压分为原发性高血压和继发性高血压。其中原发性高血压占高血压患者的90…"
